/**
 * @name Subprocess command injection via pyarrow utilities
 * @description Find uses of subprocess and os.system that may be influenced by external input in pyarrow
 * @kind problem
 * @problem.severity error
 * @id pyarrow/subprocess-injection
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.ApiGraphs
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources

module CmdInjConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      (
        call = API::moduleImport("os").getMember(["system", "popen"]).getACall() or
        call = API::moduleImport("subprocess").getMember(["Popen", "call", "run", "check_call", "check_output"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module CmdInjFlow = TaintTracking::Global<CmdInjConfig>;

from DataFlow::Node src, DataFlow::Node snk
where CmdInjFlow::flow(src, snk)
select snk, "User-controlled data reaches a subprocess command argument, which may lead to command injection."

/**
 * @name Path traversal in filesystem operations in pyarrow
 * @description Detect untrusted data flowing into file path operations (open, fsspec, pyarrow.fs)
 * @kind path-problem
 * @problem.severity error
 * @id pyarrow/path-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        // built-in open
        call = API::builtin("open").getACall() or
        // fsspec.open / fsspec.filesystem
        call = API::moduleImport("fsspec").getMember(["open", "filesystem"]).getACall() or
        // pyarrow.fs.FileSystem.open_input_file / create_dir / delete_file
        call = API::moduleImport("pyarrow.fs").getMember("FileSystem").getMember(["open_input_file", "create_dir", "delete_file", "copy_file"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches a filesystem path $@.", source.getNode(), "user input"

